#include <stdint.h>
#include "stm32f030x8.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{

	int i=0;
	/*開啟GIOB的時鐘*/
	RCC->AHBENR |=(1<<18);//使用外部設備的功能都要先開啟對的時鐘
	/***** PB2端口初始化*****/

	// ===== 1. 設定 PB1 為輸出模式 =====
	GPIOB->MODER &= ~(0x3 << (1 * 2));   // 清除 PB1 模式 (Bit 3, 2 歸零)
	GPIOB->MODER |=  (0x1 << (1 * 2));   // 設定 PB1 為輸出模式 01

	//PB2
	GPIOB->MODER &=~(0x3 << (2*2)); 	//GPIOB MODER2 清除
	GPIOB->MODER |= (0x1 << (2*2)); 	//GPIOB MODER2 設定為輸出模式01

	// ===== 3. 設定 PB15 為輸出模式 =====
	GPIOB->MODER &= ~(0x3 << (15 * 2));  // 清除 PB15 模式 (Bit 31, 30 歸零)
	GPIOB->MODER |=  (0x1 << (15 * 2));  // 設定 PB15 為輸出模式 01

	/////////////////////////////////////////////////////

	// ===== 1. 設定 PB1 為推挽輸出 (Push-Pull) =====
	GPIOB->OTYPER &= ~(0x1 << 1);        // 清除 PB1 (Bit 1 歸零)
	GPIOB->OTYPER |=  (0x0 << 1);        // 設定 PB1 為推挽模式 (可省略，因清除後即為 0)

	//PB2
	GPIOB->OTYPER &=~(0x1 << 2); 			//GPIOB OTYPER2 清除
	GPIOB->OTYPER |= (0x0 << 2);

	// ===== 3. 設定 PB15 為推挽輸出 (Push-Pull) =====
	GPIOB->OTYPER &= ~(0x1 << 15);       // 清除 PB15 (Bit 15 歸零)
	GPIOB->OTYPER |=  (0x0 << 15);       // 設定 PB15 為推挽模式

	/////////////////////////////////////////////////////


	// ===== 1. 設定 PB1 速度模式 =====
	GPIOB->OSPEEDR &= ~(0x3 << (1 * 2));   // 清除 PB1 (Bit 3, 2 歸零)
	GPIOB->OSPEEDR |=  (0x0 << (1 * 2));   // 設定 PB1 為 Low speed (可省略，因清除後即為 00)

	// PB2
	GPIOB->OSPEEDR &=~(0x3 << (2*2)); 	//GPIOB OSPEEDR2 清除
	GPIOB->OSPEEDR |= (0x0 << (2*2)); 	//GPIOB OSPEEDR2 設定為高速模式

	// ===== 3. 設定 PB15 速度模式 =====
	GPIOB->OSPEEDR &= ~(0x3 << (15 * 2));  // 清除 PB15 (Bit 31, 30 歸零)
	GPIOB->OSPEEDR |=  (0x0 << (15 * 2));  // 設定 PB15 為 Low speed


	/////////////////////////////////////////////////////


	// ===== 1. 設定 PB1 為浮空 (No Pull-up / Pull-down) =====
	GPIOB->PUPDR &= ~(0x3 << (1 * 2));   // 清除 PB1 (Bit 3, 2 歸零為 00)
	GPIOB->PUPDR |=  (0x0 << (1 * 2));   // 設定 PB1 為 00 (可省略，因清除後即為 00)

	//PB2
	GPIOB->PUPDR &=~(0x3 << (2*2)); 		//GPIOB PUPDR2 清除
	GPIOB->PUPDR |= (0x0 << (2*2)); 		//GPIOB PUPDR2設定為不上拉和不下拉

	// ===== 3. 設定 PB15 為浮空 (No Pull-up / Pull-down) =====
	GPIOB->PUPDR &= ~(0x3 << (15 * 2));  // 清除 PB15 (Bit 31, 30 歸零為 00)
	GPIOB->PUPDR |=  (0x0 << (15 * 2));  // 設定 PB15 為 00


	while(1)
	{
		// ===== 1. PB1 輸出高電位 (點亮紅燈) =====
		GPIOB->BSRR = (1 << 1);
		for(i=0;i<=150000;i++);	//小延時

		// ===== 1. PB2 輸出高電位 (點亮紅燈) =====
		GPIOB->BSRR = (1<<2); 	//PB2輸出高電位
		for(i=0;i<=150000;i++);	//小延時

		// ===== 3. PB15 輸出高電位 (點亮藍燈) =====
		GPIOB->BSRR = (1 << 15);
		for(i=0;i<=150000;i++);	//小延時


		// ===== 1. PB1 輸出低電位 (熄滅紅燈，Bit 16 + 1 = 17 寫 1) =====
		GPIOB->BSRR = (1 << 17);
		for(i=0;i<=150000;i++);	//小延時

		//PB2
		GPIOB->BSRR |= (1<<18);		//PB2輸出低電位
		for(i=0;i<=150000;i++);	//小延時

		// ===== 3. PB15 輸出低電位 (熄滅藍燈，Bit 16 + 15 = 31 寫 1) =====
		GPIOB->BSRR = (1 << 31);
		for(i=0;i<=150000;i++);	//小延時

	}

    /* Loop forever */

}
